-- 第八阶段；仅在0001–0009已成功执行后运行一次。先执行同名只读预检。
CREATE TABLE campaigns(id TEXT PRIMARY KEY,type TEXT NOT NULL CHECK(type IN('message','material','course')),title TEXT NOT NULL,summary TEXT NOT NULL DEFAULT '',body TEXT NOT NULL DEFAULT '',cover TEXT,publish_at INTEGER NOT NULL,expire_at INTEGER,status TEXT NOT NULL CHECK(status IN('draft','published','archived')),audience TEXT NOT NULL CHECK(audience IN('all','type','selected')),audience_type TEXT,version INTEGER NOT NULL DEFAULT 1,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE campaign_targets(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,campaign_id TEXT NOT NULL REFERENCES campaigns(id),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,campaign_id));
CREATE TABLE campaign_reads(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,campaign_id TEXT NOT NULL REFERENCES campaigns(id),user_id TEXT NOT NULL,at INTEGER NOT NULL,PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,campaign_id,user_id),FOREIGN KEY(tenant_id,user_id) REFERENCES users(tenant_id,id));
CREATE TABLE promo_images(id TEXT NOT NULL,tenant_id TEXT NOT NULL,owner_id TEXT NOT NULL,kind TEXT NOT NULL,mime TEXT,width INTEGER,height INTEGER,parts INTEGER NOT NULL DEFAULT 0,part_keys TEXT NOT NULL DEFAULT '[]',bytes INTEGER NOT NULL DEFAULT 0,ready INTEGER NOT NULL DEFAULT 0,version INTEGER NOT NULL DEFAULT 1,created_at INTEGER NOT NULL,PRIMARY KEY(tenant_id,id),UNIQUE(id));
CREATE TABLE poster_templates(id TEXT PRIMARY KEY,campaign_id TEXT NOT NULL REFERENCES campaigns(id),image_key TEXT NOT NULL REFERENCES promo_images(id),width INTEGER NOT NULL,height INTEGER NOT NULL,slots TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE poster_outputs(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,template_id TEXT NOT NULL REFERENCES poster_templates(id),user_id TEXT NOT NULL,action TEXT NOT NULL CHECK(action IN('view','download','save')),at INTEGER NOT NULL,PRIMARY KEY(tenant_id,id));
CREATE TABLE tenant_promo_assets(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL DEFAULT 'brand',logo_key TEXT REFERENCES promo_images(id),qr_key TEXT REFERENCES promo_images(id),updated_by TEXT NOT NULL,updated_at INTEGER NOT NULL,version INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(tenant_id,id));
CREATE TABLE partner_courses(id TEXT PRIMARY KEY,campaign_id TEXT NOT NULL UNIQUE REFERENCES campaigns(id),lecturer TEXT NOT NULL,detail_image_key TEXT REFERENCES promo_images(id),seat_price INTEGER CHECK(seat_price IS NULL OR (typeof(seat_price)='integer' AND seat_price>=0)),suggested_price INTEGER CHECK(suggested_price IS NULL OR (typeof(suggested_price)='integer' AND suggested_price>=0)),min_size INTEGER NOT NULL CHECK(min_size>=1),apply_deadline INTEGER NOT NULL,status TEXT NOT NULL CHECK(status IN('recruiting','opened','running','ended','failed')),reason TEXT NOT NULL DEFAULT '',version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE partner_sessions(id TEXT PRIMARY KEY,course_id TEXT NOT NULL REFERENCES partner_courses(id),start_at TEXT NOT NULL,duration INTEGER NOT NULL CHECK(duration IN(30,45,60)),meeting_no TEXT NOT NULL DEFAULT '',meeting_url TEXT NOT NULL DEFAULT '',cancelled INTEGER NOT NULL DEFAULT 0,version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE course_applications(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,course_id TEXT NOT NULL REFERENCES partner_courses(id),est_size INTEGER CHECK(est_size BETWEEN 1 AND 200),unsure INTEGER NOT NULL DEFAULT 0,contact_user_id TEXT NOT NULL,note TEXT NOT NULL DEFAULT '',status TEXT NOT NULL CHECK(status IN('applied','following','confirmed','opened','failed','withdrawn')),confirmed_size INTEGER NOT NULL DEFAULT 0 CHECK(confirmed_size BETWEEN 0 AND 200),seat_price INTEGER CHECK(seat_price IS NULL OR (typeof(seat_price)='integer' AND seat_price>=0)),consultant TEXT NOT NULL DEFAULT '',consultant_note TEXT NOT NULL DEFAULT '',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,version INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,course_id),FOREIGN KEY(tenant_id,contact_user_id) REFERENCES users(tenant_id,id));
CREATE TABLE partner_rosters(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,course_id TEXT NOT NULL REFERENCES partner_courses(id),student_id TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,course_id,student_id),FOREIGN KEY(tenant_id,student_id) REFERENCES students(tenant_id,id));
CREATE TABLE partner_write_guards(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,PRIMARY KEY(tenant_id,id));
ALTER TABLE lessons ADD COLUMN source_course_id TEXT REFERENCES partner_courses(id);
ALTER TABLE lessons ADD COLUMN source_session_id TEXT REFERENCES partner_sessions(id);
CREATE UNIQUE INDEX partner_lesson_once ON lessons(tenant_id,source_session_id) WHERE source_session_id IS NOT NULL;
CREATE INDEX promo_live ON campaigns(status,publish_at,expire_at);
CREATE INDEX promo_applications_course ON course_applications(course_id,status);
CREATE TRIGGER partner_lesson_protect_update BEFORE UPDATE ON lessons WHEN OLD.source_course_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM partner_write_guards WHERE tenant_id=OLD.tenant_id) AND NOT EXISTS(SELECT 1 FROM trusted_imports WHERE tenant_id=OLD.tenant_id) BEGIN SELECT RAISE(ABORT,'partner_readonly'); END;
CREATE TRIGGER partner_lesson_protect_delete BEFORE DELETE ON lessons WHEN OLD.source_course_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM partner_write_guards WHERE tenant_id=OLD.tenant_id) AND NOT EXISTS(SELECT 1 FROM trusted_imports WHERE tenant_id=OLD.tenant_id) BEGIN SELECT RAISE(ABORT,'partner_readonly'); END;
CREATE TRIGGER partner_participant_protect_insert BEFORE INSERT ON lesson_participants WHEN EXISTS(SELECT 1 FROM lessons WHERE tenant_id=NEW.tenant_id AND id=NEW.lesson_id AND source_course_id IS NOT NULL) AND NOT EXISTS(SELECT 1 FROM partner_write_guards WHERE tenant_id=NEW.tenant_id) AND NOT EXISTS(SELECT 1 FROM trusted_imports WHERE tenant_id=NEW.tenant_id) BEGIN SELECT RAISE(ABORT,'partner_readonly'); END;
CREATE TRIGGER partner_participant_protect_update BEFORE UPDATE ON lesson_participants WHEN EXISTS(SELECT 1 FROM lessons WHERE tenant_id=OLD.tenant_id AND id=OLD.lesson_id AND source_course_id IS NOT NULL) AND NOT EXISTS(SELECT 1 FROM partner_write_guards WHERE tenant_id=OLD.tenant_id) AND NOT EXISTS(SELECT 1 FROM trusted_imports WHERE tenant_id=OLD.tenant_id) BEGIN SELECT RAISE(ABORT,'partner_readonly'); END;
CREATE TRIGGER partner_participant_protect_delete BEFORE DELETE ON lesson_participants WHEN EXISTS(SELECT 1 FROM lessons WHERE tenant_id=OLD.tenant_id AND id=OLD.lesson_id AND source_course_id IS NOT NULL) AND NOT EXISTS(SELECT 1 FROM partner_write_guards WHERE tenant_id=OLD.tenant_id) AND NOT EXISTS(SELECT 1 FROM trusted_imports WHERE tenant_id=OLD.tenant_id) BEGIN SELECT RAISE(ABORT,'partner_readonly'); END;

CREATE TRIGGER partner_source_insert BEFORE INSERT ON lessons WHEN (NEW.source_course_id IS NOT NULL OR NEW.source_session_id IS NOT NULL) AND NOT EXISTS(SELECT 1 FROM partner_write_guards WHERE tenant_id=NEW.tenant_id) AND NOT EXISTS(SELECT 1 FROM trusted_imports WHERE tenant_id=NEW.tenant_id) BEGIN SELECT RAISE(ABORT,'partner_readonly'); END;
CREATE TRIGGER partner_source_update BEFORE UPDATE OF source_course_id,source_session_id ON lessons WHEN NOT EXISTS(SELECT 1 FROM partner_write_guards WHERE tenant_id=NEW.tenant_id) AND NOT EXISTS(SELECT 1 FROM trusted_imports WHERE tenant_id=NEW.tenant_id) BEGIN SELECT RAISE(ABORT,'partner_readonly'); END;

CREATE TRIGGER promo_image_tenant BEFORE INSERT ON promo_images WHEN NEW.tenant_id<>'platform' AND NOT EXISTS(SELECT 1 FROM tenants WHERE id=NEW.tenant_id) BEGIN SELECT RAISE(ABORT,'invalid_image_tenant'); END;
